@SuppressWarnings("unchecked")
public static void addToClassPath(Vector<URL> cpV, String dir) {
    if (cpV == null) {
        throw new IllegalArgumentException("Classpath vector cannot be null");
    }
    if (dir == null) {
        throw new IllegalArgumentException("Directory path cannot be null");
    }
    java.io.File dirFile = new java.io.File(dir);
    if (!dirFile.exists() || !dirFile.isDirectory()) {
        throw new IllegalArgumentException("Directory does not exist or is not a directory: " + dir);
    }
    java.io.File[] files = dirFile.listFiles();
    if (files == null) {
        return;
    }
    for (java.io.File f : files) {
        if (f.isFile() && f.getName().toLowerCase().endsWith(".jar")) {
            try {
                java.net.URL url = f.toURI().toURL();
                cpV.add(url);
            } catch (java.net.MalformedURLException e) {
                System.err.println("Failed to convert file to URL: " + f.getAbsolutePath());
            } catch (SecurityException e) {
                System.err.println("Security exception when accessing file: " + f.getAbsolutePath());
            }
        }
    }
}

